#include <bits/stdc++.h>
using namespace std;

class RPSGame {
public:
    int minRemaining;

    void evaluatePairs(vector<vector<int>>& pairs, vector<int> a, vector<int> b) {
        for (auto& p : pairs) {
            int m = min(a[p[0]], b[p[1]]);
            b[p[1]] -= m;
            a[p[0]] -= m;
        }
        int sum = 0;
        for (int v : a) sum += v;
        minRemaining = min(minRemaining, sum);
    }

    void generatePermutations(vector<vector<int>>& pairs, int start, vector<int> a, vector<int> b) {
        evaluatePairs(pairs, a, b);
        for (int i = start; i < (int)pairs.size(); i++) {
            swap(pairs[i], pairs[start]);
            generatePermutations(pairs, start + 1, a, b);
            swap(pairs[i], pairs[start]);
        }
    }

    void process(istream& in, ostream& out) {
        int n;
        in >> n;
        vector<int> a(3), b(3);
        minRemaining = INT_MAX;
        vector<string> aLine(3), bLine(3);
        for (int i = 0; i < 3; i++) {
            in >> aLine[i];
        }
        for (int i = 0; i < 3; i++) {
            in >> bLine[i];
        }
        for (int i = 0; i < 3; i++) {
            a[i] = stoi(aLine[i]);
            b[i] = stoi(bLine[i]);
        }
        int maxScore = min(a[0], b[1]) + min(a[1], b[2]) + min(a[2], b[0]);
        vector<vector<int>> pairs = {
            {0, 0},
            {1, 1},
            {2, 2},
            {0, 2},
            {1, 0},
            {2, 1}
        };
        generatePermutations(pairs, 0, a, b);
        out << minRemaining << " " << maxScore << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    RPSGame game;
    game.process(cin, cout);
    return 0;
}

